#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

typedef struct {
    int g;
    int len;
} Pair;

typedef struct {
    long long ans;
    int total_gcd;
    int plen;
    int slen;
    int len;
    Pair pref[32];
    Pair suff[32];
} Node;

int S[MAXN];
Node tree[4 * MAXN];

static inline int gcd(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

void make_leaf(Node *node, int val) {
    node->len = 1;
    node->total_gcd = val;
    if (val > 1) {
        node->ans = 1;
        node->plen = 1;
        node->pref[0].g = val;
        node->pref[0].len = 1;
        node->slen = 1;
        node->suff[0].g = val;
        node->suff[0].len = 1;
    } else {
        node->ans = 0;
        node->plen = 0;
        node->slen = 0;
    }
}

Node merge(const Node *A, const Node *B) {
    Node res;
    res.len = A->len + B->len;
    res.total_gcd = gcd(A->total_gcd, B->total_gcd);
    res.ans = A->ans + B->ans;

    for (int i = 0; i < A->slen; i++) {
        for (int j = 0; j < B->plen; j++) {
            if (gcd(A->suff[i].g, B->pref[j].g) > 1) {
                res.ans += (long long)A->suff[i].len * B->pref[j].len;
            }
        }
    }

    // Prefixo
    res.plen = 0;
    for (int i = 0; i < A->plen; i++) {
        res.pref[res.plen++] = A->pref[i];
    }
    if (A->total_gcd > 1) {
        for (int i = 0; i < B->plen; i++) {
            int g = gcd(A->total_gcd, B->pref[i].g);
            if (g > 1) {
                if (res.plen > 0 && res.pref[res.plen - 1].g == g) {
                    res.pref[res.plen - 1].len += B->pref[i].len;
                } else {
                    res.pref[res.plen].g = g;
                    res.pref[res.plen].len = B->pref[i].len;
                    res.plen++;
                }
            } else {
                break;
            }
        }
    }

    // Sufixo
    res.slen = 0;
    for (int i = 0; i < B->slen; i++) {
        res.suff[res.slen++] = B->suff[i];
    }
    if (B->total_gcd > 1) {
        for (int i = 0; i < A->slen; i++) {
            int g = gcd(B->total_gcd, A->suff[i].g);
            if (g > 1) {
                if (res.slen > 0 && res.suff[res.slen - 1].g == g) {
                    res.suff[res.slen - 1].len += A->suff[i].len;
                } else {
                    res.suff[res.slen].g = g;
                    res.suff[res.slen].len = A->suff[i].len;
                    res.slen++;
                }
            } else {
                break;
            }
        }
    }

    return res;
}

void build(int node, int l, int r) {
    if (l == r) {
        make_leaf(&tree[node], S[l]);
        return;
    }
    int mid = (l + r) / 2;
    build(2 * node, l, mid);
    build(2 * node + 1, mid + 1, r);
    tree[node] = merge(&tree[2 * node], &tree[2 * node + 1]);
}

void update(int node, int l, int r, int idx, int val) {
    if (l == r) {
        make_leaf(&tree[node], val);
        return;
    }
    int mid = (l + r) / 2;
    if (idx <= mid) {
        update(2 * node, l, mid, idx, val);
    } else {
        update(2 * node + 1, mid + 1, r, idx, val);
    }
    tree[node] = merge(&tree[2 * node], &tree[2 * node + 1]);
}

Node query(int node, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) {
        return tree[node];
    }
    int mid = (l + r) / 2;
    if (qr <= mid) {
        return query(2 * node, l, mid, ql, qr);
    }
    if (ql > mid) {
        return query(2 * node + 1, mid + 1, r, ql, qr);
    }
    Node left = query(2 * node, l, mid, ql, qr);
    Node right = query(2 * node + 1, mid + 1, r, ql, qr);
    return merge(&left, &right);
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        scanf("%d", &S[i]);
    }

    build(1, 1, n);

    for (int k = 0; k < m; k++) {
        int type;
        scanf("%d", &type);
        if (type == 1) {
            int idx, val;
            scanf("%d %d", &idx, &val);
            update(1, 1, n, idx, val);
        } else {
            int l, r;
            scanf("%d %d", &l, &r);
            Node ans = query(1, 1, n, l, r);
            printf("%lld\n", ans.ans);
        }
    }

    return 0;
}
